import DataLoader from 'dataloader';
import { Query, Resolver } from '@nestjs/graphql';
import { Injectable } from '@nestjs/common';

interface UserRecord {
  id: string;
  name: string;
}

interface PostRecord {
  id: string;
  title: string;
  authorId: string;
}

interface UserDataSource {
  query<T>(sql: string, params: unknown[]): Promise<T[]>;
}

/**
 * Built fresh per incoming request inside the Apollo context factory, so the
 * loader's in-memory cache never leaks results across requests.
 */
export function createUserLoader(db: UserDataSource): DataLoader<string, UserRecord> {
  return new DataLoader<string, UserRecord>(async (ids: readonly string[]) => {
    // Exactly one multi-key round-trip per batch tick.
    const placeholders = ids.map((_, i) => `$${i + 1}`).join(', ');
    const rows = await db.query<UserRecord>(
      `SELECT * FROM users WHERE id IN (${placeholders})`,
      [...ids],
    );
    const rowById = new Map(rows.map((row) => [row.id, row]));

    // One log line per batch dispatch — this is the fingerprint we check in prod.
    // eslint-disable-next-line no-console
    console.log(`[batch] users -> [${ids.join(',')}]`);

    // DataLoader requires the output array to line up 1:1 with the input ids.
    return ids.map((id) => rowById.get(id) ?? new Error(`User ${id} not found`));
  });
}

export interface GraphQLContext {
  userLoader: DataLoader<string, UserRecord>;
}

@Injectable()
class PostService {
  async findAll(): Promise<PostRecord[]> {
    return [
      { id: 'p1', title: 'Intro to GraphQL', authorId: 'u1' },
      { id: 'p2', title: 'DataLoader deep dive', authorId: 'u2' },
      { id: 'p3', title: 'Schema stitching', authorId: 'u3' },
    ];
  }
}

@Resolver('Query')
export class PostQueryResolver {
  constructor(private readonly postService: PostService) {}

  @Query('postsWithAuthors')
  async postsWithAuthors(
    _parent: unknown,
    _args: unknown,
    context: GraphQLContext,
  ): Promise<Array<PostRecord & { author: UserRecord }>> {
    const posts = await this.postService.findAll();

    const postsWithAuthors: Array<PostRecord & { author: UserRecord }> = [];
    for (const post of posts) {
      // Awaiting the pending load right here, inside the loop, fully settles
      // this iteration before the next one calls `.load()` again — each key
      // lands in its own dispatch window instead of a shared one.
      const author = await context.userLoader.load(post.authorId);
      postsWithAuthors.push({ ...post, author });
    }

    return postsWithAuthors;
  }
}
